/* 02_outflow_engine.sas  ·  LCR stressed outflow engine */
%macro run_outflows(deposits=, scen=, out=);
  /* pull the active runtime stress scenario */
  proc sql noprint;
    select runoff_multiplier into :mult
      from &scen
     where scenario_name = "&g_scenario";
  quit;

  data &out;
    set &deposits;
    /* stressed 30-day runoff: base rate scaled by runtime multiplier */
    runoff_rate_applied = base_runoff_rate * &mult;
    outflow_eur         = balance_eur * runoff_rate_applied;
    stress_scenario     = "&g_scenario";
  run;
%mend;
%run_outflows(deposits=stg.deposit_book, scen=liq.stress_scenarios,
              out=work.outflows_by_deposit);
